/** Retention device configuration */
struct retention_config {
	/** Pointer to the parent retained memory device */
	const struct device *parent_dev;
	/** Offset within the parent retained memory device */
	off_t offset;
	/** Size of the retention area */
	size_t size;
	/** Optional prefix for data validity check */
	const uint8_t *prefix;
	/** Length of the prefix */
	size_t prefix_len;
};

/** Retention device data (currently empty as no runtime data is needed) */
struct retention_data {
	/* No runtime data needed for this simple pass-through driver */
};

ssize_t retention_size(const struct device *dev)
{
	const struct retention_config *config = dev->config;

	return config->size;
}

int retention_is_valid(const struct device *dev)
{
	const struct retention_config *config = dev->config;

	if (config->prefix == NULL || config->prefix_len == 0) {
		return -ENOTSUP; /* No prefix configured for validity check */
	}

	uint8_t read_prefix[config->prefix_len];
	int rc = retained_mem_read(config->parent_dev, config->offset, read_prefix,
				   config->prefix_len);
	if (rc != 0) {
		LOG_ERR("Failed to read prefix from retained memory: %d", rc);
		return rc;
	}

	if (memcmp(read_prefix, config->prefix, config->prefix_len) == 0) {
		return 1; /* Valid */
	} else {
		return 0; /* Not valid */
	}
}

int retention_read(const struct device *dev, off_t offset, uint8_t *buffer, size_t size)
{
	const struct retention_config *config = dev->config;

	if ((offset + size) > config->size) {
		LOG_ERR("Read out of bounds: offset %d, size %d, retention size %d",
			offset, size, config->size);
		return -EINVAL;
	}
	return retained_mem_read(config->parent_dev, config->offset + offset, buffer, size);
}

int retention_write(const struct device *dev, off_t offset, const uint8_t *buffer, size_t size)
{
	const struct retention_config *config = dev->config;

	if ((offset + size) > config->size) {
		LOG_ERR("Write out of bounds: offset %d, size %d, retention size %d",
			offset, size, config->size);
		return -EINVAL;
	}

	int rc = retained_mem_write(config->parent_dev, config->offset + offset, buffer, size);
	if (rc != 0) {
		return rc;
	}

	/* If writing to offset 0, and a prefix is configured, ensure prefix is written
	 * to mark the area as valid. This is a common pattern for retention areas.
	 */
	if (offset == 0 && config->prefix != NULL && config->prefix_len > 0) {
		rc = retained_mem_write(config->parent_dev, config->offset, config->prefix,
					config->prefix_len);
		if (rc != 0) {
			LOG_ERR("Failed to write prefix to retained memory: %d", rc);
		}
	}
	return rc;
}

int retention_clear(const struct device *dev)
{
	const struct retention_config *config = dev->config;
	uint8_t zero_buffer[CONFIG_RETENTION_BUFFER_SIZE];
	memset(zero_buffer, 0, sizeof(zero_buffer));

	int rc = 0;
	for (off_t i = 0; i < config->size; i += sizeof(zero_buffer)) {
		size_t write_len = MIN(sizeof(zero_buffer), config->size - i);
		rc = retained_mem_write(config->parent_dev, config->offset + i, zero_buffer,
					write_len);
		if (rc != 0) {
			LOG_ERR("Failed to clear retained memory at offset %d: %d", i, rc);
			break;
		}
	}

	/* After clearing, the area is no longer valid, so clear the prefix too. */
	if (rc == 0 && config->prefix != NULL && config->prefix_len > 0) {
		uint8_t empty_prefix[config->prefix_len];
		memset(empty_prefix, 0, sizeof(empty_prefix));
		rc = retained_mem_write(config->parent_dev, config->offset, empty_prefix,
					config->prefix_len);
		if (rc != 0) {
			LOG_ERR("Failed to clear prefix in retained memory: %d", rc);
		}
	}
	return rc;
}

