struct retention_config {
	/** Pointer to the underlying retained memory device. */
	const struct device *retained_mem_dev;
	/** Base offset within the retained memory device for this retention area. */
	off_t base_offset;
	/** Total size of the retention area as defined in devicetree. */
	size_t total_size;
	/** Prefix bytes used for data validity check. */
	uint8_t prefix[2];
	/** Flag indicating if a prefix is configured for this retention area. */
	bool has_prefix;
};

/**
