/**
 * @brief Calculates the user-accessible size of the retention area.
 *
 * If a prefix is configured, its size is subtracted from the total size.
 *
 * @param config Pointer to the retention device configuration.
 * @return User-accessible size in bytes.
 */
static size_t get_user_size(const struct retention_config *config)
{
	if (config->has_prefix) {
		return config->total_size > sizeof(config->prefix) ?
			   (config->total_size - sizeof(config->prefix)) : 0;
	}
	return config->total_size;
}

/**
 * @brief Calculates the actual physical offset in the retained memory.
 *
 * This accounts for the base offset of the retention area and the prefix size
 * if a prefix is used.
 *
 * @param config Pointer to the retention device configuration.
 * @param user_offset User-provided offset within the user-accessible area.
 * @return Actual physical offset in the retained memory.
 */
static off_t get_actual_offset(const struct retention_config *config, off_t user_offset)
{
	return config->base_offset + (config->has_prefix ? sizeof(config->prefix) : 0) + user_offset;
}

ssize_t retention_size(const struct device *dev)
{
	const struct retention_config *config = dev->config;

	return get_user_size(config);
}

int retention_is_valid(const struct device *dev)
{
	const struct retention_config *config = dev->config;
	uint8_t read_prefix[2];
	int rc;

	if (!config->has_prefix) {
		return -ENOTSUP;
	}

	if (config->total_size < sizeof(config->prefix)) {
		LOG_ERR("Retention area %s too small (%zu bytes) for prefix (%zu bytes)",
			dev->name, config->total_size, sizeof(config->prefix));
		return -EINVAL;
	}

#ifdef CONFIG_RETENTION_MUTEXES
	k_mutex_lock(&((struct retention_data *)dev->data)->mutex, K_FOREVER);
