	if (rc != 0) {
		LOG_ERR("Failed to read prefix from %s: %d", config->retained_mem_dev->name, rc);
	}

#ifdef CONFIG_RETENTION_MUTEXES
	k_mutex_unlock(&((struct retention_data *)dev->data)->mutex);
#endif

	if (rc != 0) {
		return rc;
	}

	if (memcmp(read_prefix, config->prefix, sizeof(read_prefix)) == 0) {
		return 1; /* Valid */
	} else {
		return 0; /* Not valid */
	}
}

